import 'package:flutter/material.dart';import 'api.dart';
class HubConfiguratorScreen extends StatefulWidget{const HubConfiguratorScreen({super.key});@override State<HubConfiguratorScreen> createState()=>_State();}
class _State extends State<HubConfiguratorScreen>{final n=TextEditingController(),d=TextEditingController(),i=TextEditingController();List hubs=[];Future<void> load()async{hubs=await adminApi.hubs();if(mounted)setState((){});}@override void initState(){super.initState();load();}Future<void> create()async{await adminApi.createHub(n.text.trim(),d.text.trim(),i.text.trim());n.clear();d.clear();i.clear();load();}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Hub name')),TextField(controller:d,decoration:const InputDecoration(labelText:'Description')),TextField(controller:i,decoration:const InputDecoration(labelText:'Icon URL')),const SizedBox(height:8),ElevatedButton(onPressed:create,child:const Text('Create Sub-Hub')),const Divider(),...hubs.map((h)=>ListTile(title:Text(h['name']??''),subtitle:Text(h['description']??''))) ]);}
